//! Support for `ws_fmt!`: builds a string template from the macro's pieces.

use crate::expr::Expr;
use crate::ir::{self, ExprKind, StrExpr, StrToken};
use crate::ty::{Any, Str};

/// A piece of a template, as generated by `ws_fmt!`.
#[doc(hidden)]
#[derive(Clone, Copy, Debug)]
pub enum Piece {
    /// Literal text.
    Text(&'static str),
    /// A reference to the argument with this index.
    Arg(usize),
}

/// Builds the template `Expr<Str>` for `ws_fmt!`.
#[doc(hidden)]
#[track_caller]
#[must_use]
pub fn template(pieces: &[Piece], args: Vec<Expr<Any>>) -> Expr<Str> {
    let mut tokens = Vec::new();
    for piece in pieces {
        match *piece {
            Piece::Text(text) => push_text(&mut tokens, text),
            Piece::Arg(i) => tokens.push(StrToken::Arg(i)),
        }
    }
    let args = args.into_iter().map(Expr::into_ir).collect();
    Expr::from_ir(ir::Expr::here(ExprKind::Str(StrExpr::Custom {
        tokens,
        args,
    })))
}

/// Appends literal text: carriage returns are dropped and adjacent text is merged.
pub(crate) fn push_text(tokens: &mut Vec<StrToken>, text: &str) {
    let text = text.replace('\r', "");
    if text.is_empty() {
        return;
    }
    match tokens.last_mut() {
        Some(StrToken::Text(prev)) => prev.push_str(&text),
        _ => tokens.push(StrToken::Text(text)),
    }
}

